window.bookSummaryJSON = "<p>There’s no such thing as Vampires… right? That’s what Jake’s good friend Ariana thought. So why did somebody drop a body covered with bites at the hospital where she works? And why is she being followed by creepy dudes? Jake wants answers, and he’s going to get them no matter the cost. He’s also going to learn that, “We do not wrestle against flesh and blood, but against the rulers, against the authorities, against the cosmic powers over this present darkness, against the spiritual forces of evil in the heavenly places.” Will Jake Muller take up a sword in this spiritual battle?</p> <p><b>Full cast of narrators:</b></p> <p><b>Dugan Sherbondy</b></p> <p><b>Sky Ziskin</b></p> <p><b>Christian Gill</b></p> <p><b>Jake Phillips</b></p> <p><b>Bill Myers</b></p> <p><b>Steve Oswald</b></p> <p><b>Chris Anthony</b></p> <p><b>Phil Lollar</b></p> <p><b>Jonathan Bullock</b></p> <p><b>Chloë Elmore</b></p> <p><b>Josh Murray</b></p> <p><b>Jonathan Cooke</b></p> <p><b>Kera O'Bryon</b></p> <p><b>Aimee Lilly</b></p> <p><b>Chris Fabry</b></p> <p><b>Charles Adams</b></p> <p><b>Jeremy Anderson</b></p> <p><b>John K. Burke</b></p> <p><b>David Cwi</b></p> <p><b>John Fornof</b></p> <p><b>Andy Harvey</b></p> <p><b>Elizabeth Kern</b></p> <p><b>Nick Mataragas</b></p> <p><b>Ruth Sorweide</b></p> <p><b>Randy Streu</b></p> <p><b>J.D. Sutter</b></p> <p><b>Micah Touche</b></p>"; 
